from langflow.custom.custom_component.component import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.data import Data
import requests
import os
import json


class CustomComponent(Component):
    display_name = "Test Output"
    description = "Use as a template to create your own component."
    documentation: str = "https://docs.langflow.org/components-custom-components"
    icon = "code"
    name = "TestOutput"

    inputs = [
        MessageTextInput(
            name="input_value",
            display_name="Input Value",
            info="This is a custom component Input",
            value="",
            tool_mode=True,
        ),
    ]

    outputs = [
        Output(display_name="Output", name="output", method="build_output"),
    ]

    def build_output(self) -> Data:
        text = self.input_value
        try:
            if hasattr(self, 'input_value') and hasattr(self.input_value, 'text'):
                text = self.input_value.text
        except Exception:
            pass

        payload = {"answer": text or ""}
        url = os.getenv("QA_SERVER_POST_ANSWER_URL", "")
        status = {}
        if url:
            try:
                resp = requests.post(url, json=payload, timeout=10)
                status = {"status_code": resp.status_code, "text": resp.text[:2048]}
            except Exception as e:
                status = {"error": str(e)}
        else:
            status = {"warning": "QA_SERVER_POST_ANSWER_URL not set"}

        data = Data(value=text)
        self.status = json.dumps(status, ensure_ascii=False)
        return data

from langflow.base.io.chat import ChatComponent
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message
import os
import requests
import json

class ChatInput(ChatComponent):
    display_name="Chat Input"
    name="ChatInput"
    inputs=[MessageTextInput(name="input_value", display_name="Input Text", value="")]
    outputs=[Output(display_name="Output Message", name="message", method="message_response")]
    async def message_response(self)->Message:
        text = self.input_value or ""
        if not text:
            try:
                url = os.getenv("QA_SERVER_GET_QUESTION_URL", "")
                if url:
                    resp = requests.get(url, timeout=10)
                    if resp.ok:
                        try:
                            data = resp.json()
                            if isinstance(data, dict):
                                text = str(data.get("question", "")) or ""
                            else:
                                text = str(data) or ""
                        except Exception:
                            text = resp.text or ""
            except Exception:
                text = ""
        return Message(text=text)

