from langflow.custom.custom_component.component import Component
from langflow.io import MessageTextInput, HandleInput, StrInput, Output
from langflow.schema.message import Message


class ParserComponent(Component):
    display_name = "Parser"
    description = "Parse and format retrieved documents"
    name = "Parser"
    icon = "code"

    inputs = [
        HandleInput(
            name="retrieved_docs",
            display_name="Retrieved Documents",
            input_types=["Data"],
            is_list=True,
        ),
        StrInput(
            name="pattern",
            display_name="Format Pattern",
            value="检索片段：\n{content}\n\n",
        ),
    ]

    outputs = [
        Output(display_name="Formatted Context", name="context", method="parse_docs"),
    ]

    def parse_docs(self) -> Message:
        if not self.retrieved_docs:
            return Message(text="")

        formatted = []
        for doc in self.retrieved_docs:
            content = doc.text if hasattr(doc, 'text') else str(doc)
            formatted.append(self.pattern.format(content=content))

        result_text = "".join(formatted)
        return Message(text=result_text)
